<template><div class="feedback"><span>这个回答有帮助吗？</span><el-button link :type="value?.rating==='helpful'?'primary':''" @click="submit('helpful')">👍 有帮助</el-button><el-button link :type="value?.rating==='unhelpful'?'danger':''" @click="open=true">👎 没帮助</el-button><el-dialog v-model="open" title="告诉我们哪里需要改进" width="420px"><el-select v-model="reason" placeholder="选择原因" style="width:100%"><el-option v-for="x in reasons" :key="x[0]" :label="x[1]" :value="x[0]"/></el-select><el-input v-model="comment" type="textarea" :rows="3" maxlength="1000" show-word-limit style="margin-top:12px"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :disabled="!reason" @click="submit('unhelpful')">提交</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ref}from"vue";import{ElMessage}from"element-plus";import{saveAnswerFeedback}from"../../api/conversation/feedback";import type{AnswerFeedback}from"../../types";const p=defineProps<{messageId:number}>();const value=ref<AnswerFeedback|null>(null),open=ref(false),reason=ref(""),comment=ref("");const reasons=[["wrong","内容错误"],["outdated","信息过期"],["bad_citation","引用不正确"],["incomplete","回答不完整"],["no_answer","没有回答到"],["other","其他"]];async function submit(r:"helpful"|"unhelpful"){try{value.value=await saveAnswerFeedback(p.messageId,{rating:r,...(r==="unhelpful"?{reason_code:reason.value,comment:comment.value}:{})});open.value=false;ElMessage.success("感谢反馈");}catch(e){ElMessage.error((e as Error).message);}}</script>
<style scoped>.feedback{display:flex;align-items:center;gap:4px;margin-top:10px;padding-top:8px;border-top:1px solid var(--el-border-color-lighter);font-size:12px;color:var(--el-text-color-secondary)}</style>
